package com.farika.soundflow;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;
/** Actual Android animations, local WAV and measured view properties. No cloud writes. */
final class MotionCases {
 static Object field(Object o,String name)throws Exception{java.lang.reflect.Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
 static void main(Instrumentation t,Runnable r){final Throwable[] failure={null};t.runOnMainSync(()->{try{r.run();}catch(Throwable e){failure[0]=e;}});if(failure[0]!=null)throw new RuntimeException(failure[0]);}
 static void run(Instrumentation t,String mode){Context c=t.getTargetContext();Bundle out=new Bundle();ResumeCases helper=new ResumeCases(t);try{
  c.getSharedPreferences("appearance",0).edit().putBoolean("motion",true).commit();helper.fixture();Activity a=helper.launch();t.waitForIdleSync();
  if(mode.equals("motion-disabled")){helper.check(!Motion.enabled(c),"system_reduced_motion_overrides_app");main(t,()->{View v=new View(c);Motion.enter(v);helper.check(v.getAlpha()==1&&v.getTranslationY()==0,"reduced_motion_no_hidden_or_translated_view");});out.putInt("checks",helper.n);t.finish(Activity.RESULT_OK,out);return;}
  helper.check(Motion.enabled(c),"motion_default_enabled");final View[] button={null},body={null},wave={null};main(t,()->{try{body[0]=(View)field(a,"body");LinearLayout root=(LinearLayout)field(a,"root");wave[0]=((android.view.ViewGroup)root.getChildAt(0)).getChildAt(0);button[0]=SoundFlowUi.button(c,"QA",true,()->{});((LinearLayout)body[0]).addView(button[0],0);Motion.enter(body[0]);helper.check(body[0].getAlpha()==0,"tab_entry_starts_transparent");}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(700);main(t,()->helper.check(body[0].getAlpha()==1&&body[0].getTranslationY()==0,"tab_entry_settles_visible_without_offset"));
  main(t,()->button[0].setPressed(true));Thread.sleep(250);main(t,()->helper.check(button[0].getScaleX()<.99f&&button[0].getScaleX()>.94f,"button_press_scales_without_touch_interception"));main(t,()->button[0].setPressed(false));Thread.sleep(300);main(t,()->helper.check(Math.abs(button[0].getScaleX()-1)<.001,"button_release_restores_scale"));
  helper.play();final float[] phase={0};main(t,()->{try{phase[0]=(Float)field(wave[0],"phase");}catch(Exception e){throw new RuntimeException(e);}});boolean changed=false;for(int k=0;k<25;k++){Thread.sleep(200);final boolean[] moving={false};main(t,()->{try{moving[0]=(Float)field(wave[0],"phase")!=phase[0];}catch(Exception e){throw new RuntimeException(e);}});if(moving[0]){changed=true;break;}}final boolean hasChanged=changed;main(t,()->{try{helper.check(hasChanged,"wave_bars_animate_during_playback phase="+phase[0]+" now="+field(wave[0],"phase")+" focus="+wave[0].hasWindowFocus()+" shown="+wave[0].isShown()+" playing="+PlaybackService.instance.isPlaying()+" enabled="+Motion.enabled(c));PlaybackService.instance.pause();}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(300);main(t,()->{try{phase[0]=(Float)field(wave[0],"phase");}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(800);main(t,()->{try{helper.check((Float)field(wave[0],"phase")==phase[0],"paused_wave_not_continuously_animated");}catch(Exception e){throw new RuntimeException(e);}});
  c.getSharedPreferences("appearance",0).edit().putBoolean("motion",false).commit();main(t,()->{Motion.refresh((View)body[0]);Motion.enter(body[0]);helper.check(!Motion.enabled(c)&&body[0].getAlpha()==1&&button[0].getStateListAnimator()==null,"app_motion_off_applies_immediately");});
  helper.stop();out.putInt("checks",helper.n);t.finish(Activity.RESULT_OK,out);
 }catch(Throwable e){out.putString("failure",e.getClass().getSimpleName()+": "+e.getMessage());t.finish(Activity.RESULT_CANCELED,out);}}
}
